-- generated by build.py from gamecode.inc.lua (do not edit by hand) ----------------------------------------------
-- The same block is put into the battle script and into the main menu check, so both judge the game build the same way.
local P_SITE = '--P_SITE--'
local SITE_OFF = --SITE_OFF--
local P_RET = '--P_RET--'
local RET_OFF = --RET_OFF--
local P_UID = '--P_UID--'
local UID_OFF = --UID_OFF--
local AT_SITE = '--AT_SITE--'
local AT_RET = '--AT_RET--'
local NEEDED = { 'find_pattern', 'function_start', 'hook_info', 'code_cave', 'game_alloc', 'alloc', 'read', 'read_original', 'write', 'read_pointer', 'read_uint32', 'ud_topointer', 'add', 'is_null', 'uint32', 'tostring' }

-- nil when this memreader can do everything the mod needs, else the reason as text
local function memreader_problem(mr)
	for _, name in ipairs(NEEDED) do
		if type(mr[name]) ~= 'function' then return 'this memreader has no ' .. name .. ' (memreader Plus 0.10.0 or newer is needed)' end
	end
	return nil
end

local function one_match(mr, pattern, name)
	local address, count = mr.find_pattern(pattern)
	if not address or count ~= 1 then error(('the %s code was found %s times, expected 1'):format(name, tostring(count)), 0) end
	return address
end

-- Finds the places in the game code the mod works with. Only reads; raises an error (text) when this game build does not fit.
local function locate(mr)
	local problem = memreader_problem(mr)
	if problem then error(problem, 0) end
	local site = mr.add(one_match(mr, P_SITE, 'line of fire check'), SITE_OFF)
	local ret = mr.add(one_match(mr, P_RET, 'no-hit exit'), RET_OFF)
	local uid = mr.add(one_match(mr, P_UID, 'unit id'), UID_OFF)
	if mr.read_original(site, 0, #AT_SITE) ~= AT_SITE then error('unexpected code at the cave site', 0) end
	if mr.read_original(ret, 0, #AT_RET) ~= AT_RET then error('unexpected code at the no-hit exit', 0) end
	local site_function = mr.function_start(site)
	local ret_function = mr.function_start(ret)
	if not site_function or site_function ~= ret_function then error('cave site and no-hit exit are not in the same function', 0) end
	local uid_offset = mr.read_uint32(uid, 0)
	if type(uid_offset) ~= 'number' or uid_offset < 8 or uid_offset > 0x100000 then error('implausible unit id offset ' .. tostring(uid_offset), 0) end
	return { site = site, ret = ret, uid_offset = uid_offset }
end
-- end of the shared part ----------------------------------------------------------------------------------------------
